import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { CSSProperties, useMemo, useEffect, useState } from 'react';
import {
  IStockDetailsReport,
  IStockDetails,
} from '../../../core/Interface/stockDetailReport.interface';
import usePageQuery from '../../../core/hooks/usePageQuery';
import { useStockReportQuery } from '../../posApi';
import useStockAdjustReportColumns from './useStockAdjustReportColumns';

const useStockAdjustReport = () => {
  const { page, setPage } = usePageQuery();
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data: reportData,
    isLoading,
    isFetching,
    error,
  } = useStockReportQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText: '',
  });

  useEffect(() => {
    setPage(pagination.pageIndex);
  }, [pagination.pageIndex, setPage]);

  const ReportDetailsMemo = useMemo(() => {
    return reportData?.data as IStockDetailsReport;
  }, [reportData?.data]);

  const filteredData = useMemo(() => {
    const text = searchText.toLowerCase().trim();
    return (
      reportData &&
      ReportDetailsMemo.data &&
      ReportDetailsMemo.data.filter((record: IStockDetails) => {
        const name = record.productName.toLowerCase();
        const code = record.productCode.toLowerCase();
        return name?.includes(text) || code?.includes(text);
      })
    );
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ReportDetailsMemo, searchText]);


  const columns = useStockAdjustReportColumns(
    pagination.pageIndex,
    pagination.pageSize
  );

  const table = useReactTable({
    data: error ? [] : filteredData ?? [],
    meta: {
      getRowStyles: (row: Row<IStockDetails>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: ReportDetailsMemo?.totalRecords ?? 0,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: ReportDetailsMemo?.totalRecords ?? 0,
    searchText,
    setSearchText,
  };
};

export default useStockAdjustReport;
